from sklearn.metrics import mean_absolute_percentage_error, mean_absolute_error, mean_squared_error
series = df.sales_units.copy()

def forecast_snaive(train, target_date):
    if target_date - pd.DateOffset(years=1) in train.index:
        return train.loc[target_date - pd.DateOffset(years=1)]
    return train.iloc[-1]

def forecast_snaive_drift_mult(train, target_date):
    lagdate=target_date-pd.DateOffset(years=1)
    base=train.loc[lagdate] if lagdate in train.index else train.iloc[-1]
    if len(train)>=24:
        ratio=train.iloc[-12:].mean()/train.iloc[-24:-12].mean()
    else:
        ratio=1.0
    # shrink ratio toward 1 due small n?
    return base*ratio

def forecast_snaive_drift_add(train,target_date):
    lagdate=target_date-pd.DateOffset(years=1)
    base=train.loc[lagdate] if lagdate in train.index else train.iloc[-1]
    if len(train)>=24:
        diff=train.iloc[-12:].mean()-train.iloc[-24:-12].mean()
    else:
        diff=0.0
    return base+diff

def forecast_mom_ratio_dec(train,target_date):
    # previous December -> target Jan ratio avg available Jan/prev Dec
    ratios=[]
    for date,val in train.items():
        if date.month==1:
            prev=date-pd.DateOffset(months=1)
            if prev in train.index: ratios.append(val/train.loc[prev])
    if not ratios: return train.iloc[-1]
    return train.iloc[-1]*np.mean(ratios) # if target is next month only from Dec

def forecast_ols_log(train,target_date, trend=True):
    dd=pd.DataFrame({'y':train.values}, index=train.index).reset_index().rename(columns={'index':'date'})
    dd['t']=np.arange(len(dd))
    dd['month']=dd['date'].dt.month
    dd['logy']=np.log(dd.y)
    if len(dd) < 18: return np.nan
    formula='logy ~ C(month)' + (' + t' if trend else '')
    mod=smf.ols(formula,dd).fit()
    fut=pd.DataFrame({'date':[target_date], 't':[len(dd)], 'month':[target_date.month]})
    pred=float(np.exp(mod.predict(fut)[0]))
    return pred

def forecast_ets_add(train,target_date):
    if len(train)<24: return np.nan
    try:
        fit=ExponentialSmoothing(train, trend=None, seasonal='add', seasonal_periods=12, initialization_method='estimated').fit()
        return fit.forecast(1).iloc[0]
    except Exception:
        return np.nan
def forecast_ets_mul(train,target_date):
    if len(train)<24: return np.nan
    try:
        fit=ExponentialSmoothing(train, trend=None, seasonal='mul', seasonal_periods=12, initialization_method='estimated').fit()
        return fit.forecast(1).iloc[0]
    except Exception:
        return np.nan

forecasters = {
    'snaive': forecast_snaive,
    'snaive_mult': forecast_snaive_drift_mult,
    'snaive_add': forecast_snaive_drift_add,
    'jan_dec_ratio': forecast_mom_ratio_dec,
    'ols_log_trend': lambda tr,td: forecast_ols_log(tr,td,True),
    'ols_log_notrend': lambda tr,td: forecast_ols_log(tr,td,False),
    'ets_add': forecast_ets_add,
    'ets_mul': forecast_ets_mul,
}
# rolling one-step target from 2024-01 onwards
rows=[]
for target_date in series.index:
    train=series.loc[:target_date-pd.DateOffset(months=1)]
    if len(train)<15: continue
    actual=series.loc[target_date]
    for name,fn in forecasters.items():
        pred=fn(train,target_date)
        if np.isfinite(pred):
            rows.append((target_date,name,pred,actual,abs(pred-actual),abs(pred-actual)/actual))
bt=pd.DataFrame(rows, columns=['date','model','pred','actual','ae','ape'])
summary=bt.groupby('model').agg(n=('ape','size'), mape=('ape','mean'), mae=('ae','mean'), rmse=('ae',lambda x: np.sqrt(np.mean(x*x)))).sort_values('mape')
